{%- set ns = namespace(loans=[], sources=0, offline=0, soon=0, overdue=0) -%}
{%- for s in expand(integration_entities('winbiap')) if s.entity_id.startswith('sensor.') and s.attributes.loans is defined -%}
{%- set ns.sources = ns.sources + 1 -%}
{%- if s.state in ['unavailable', 'unknown'] -%}{%- set ns.offline = ns.offline + 1 -%}
{%- else -%}{%- set ns.loans = ns.loans + s.attributes.loans -%}{%- endif -%}
{%- endfor -%}
{%- set loans = ns.loans | sort(attribute='due_date') -%}
{%- for loan in loans -%}
{%- set date = as_datetime(loan.due_date, none) -%}
{%- if date -%}{%- set days = (date.date() - now().date()).days -%}
{%- if days < 0 -%}{%- set ns.overdue = ns.overdue + 1 -%}
{%- elif days <= 7 -%}{%- set ns.soon = ns.soon + 1 -%}{%- endif -%}{%- endif -%}
{%- endfor -%}

<div class="intro"><small>MEINE BÜCHEREI</small><h1>Lesestoff zu Hause</h1><p>Alle Ausleihen auf einen Blick · nach Rückgabedatum sortiert</p></div>
{% if ns.sources == 0 or ns.offline > 0 %}
<ha-alert alert-type="warning">Das Büchereikonto ist gerade nicht vollständig erreichbar. Bitte später erneut prüfen.</ha-alert>
{% endif %}
<div class="stats"><div><strong>{{ loans | count }}</strong><span>Ausgeliehen</span></div><div><strong>{{ ns.soon }}</strong><span>In 7 Tagen fällig</span></div><div><strong>{{ ns.overdue }}</strong><span>Überfällig</span></div></div>
{% if loans %}
<h2>Deine ausgeliehenen Bücher</h2>
<div class="books">
{%- for loan in loans -%}
{%- set date = as_datetime(loan.due_date, none) -%}
{%- set days = (date.date() - now().date()).days if date else none -%}
{%- set cover = namespace(url=none) -%}
{%- for img in expand(integration_entities('winbiap')) if img.entity_id.startswith('image.') and img.state not in ['unavailable','unknown'] and img.attributes.title == loan.title and img.attributes.due_date == loan.due_date -%}
{%- set cover.url = img.attributes.entity_picture | default(none) -%}
{%- endfor -%}
<div class="book"><div class="cover">{% if cover.url %}<img src="{{ cover.url | e }}" alt="Buchcover" loading="lazy">{% else %}<ha-icon icon="mdi:book-open-page-variant"></ha-icon><small>Kein Cover</small>{% endif %}</div><div class="details"><h3>{{ loan.title | e }}</h3><p class="author">{{ (loan.author or '') | e }}</p>{% set tag = 'em' if days is not none and days < 0 else 'mark' if days is not none and days <= 7 else 'span' %}<{{ tag }}>{% if days is none %}Frist unbekannt{% elif days < 0 %}{{ -days }} {{ 'Tag' if days == -1 else 'Tage' }} überfällig{% elif days == 0 %}Heute fällig{% elif days == 1 %}Morgen fällig · noch 1 Tag{% else %}Noch {{ days }} Tage{% endif %}</{{ tag }}><p class="date">Rückgabe: <strong>{{ date.strftime('%d.%m.%Y') if date else 'unbekannt' }}</strong></p></div></div>
{%- endfor -%}
</div>
{% elif ns.sources > 0 and ns.offline == 0 %}
<ha-alert alert-type="success">Alles zurückgegeben. Momentan sind keine Bücher ausgeliehen.</ha-alert>
{% endif %}
<p class="footer">Automatischer Abgleich alle 30 Minuten · Tagesangaben aktualisieren sich automatisch.</p>

style.ha-markdown$:
ha-markdown-element > div:first-of-type small { color: var(--primary-color); font-weight: 700; letter-spacing: .14em; font-size: 11px; }
h1 { font-size: 30px; line-height: 1.2; margin: 10px 0 !important; font-weight: 750; }
ha-markdown-element > div:first-of-type p, ha-markdown-element > p:last-child { color: var(--secondary-text-color); }
ha-markdown-element > div:nth-of-type(2) { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 12px; margin: 24px 0 32px; }
ha-markdown-element > div:nth-of-type(2) > div { background: var(--ha-card-background,var(--card-background-color)); border: 1px solid var(--divider-color); border-radius: 18px; padding: 20px 16px; }
ha-markdown-element > div:nth-of-type(2) strong { display: block; font-size: 32px; line-height: 1.2; }
ha-markdown-element > div:nth-of-type(2) span { display: block; margin-top: 8px; font-size: 13px; color: var(--secondary-text-color); }
h2 { font-size: 20px; margin-bottom: 18px !important; }
ha-markdown-element > div:nth-of-type(3) { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 16px; }
ha-markdown-element > div:nth-of-type(3) > div { display: flex; gap: 18px; padding: 20px; border: 1px solid var(--divider-color); background: var(--ha-card-background,var(--card-background-color)); border-radius: 18px; min-width: 0; }
ha-markdown-element > div:nth-of-type(3) > div > div:first-child { width: 100px; flex: 0 0 100px; align-self: flex-start; min-height: 140px; display: flex; align-items: center; justify-content: center; flex-direction: column; background: var(--secondary-background-color); border-radius: 7px; overflow: hidden; }
ha-markdown-element > div:nth-of-type(3) > div > div:first-child img { width: 100%; max-height: 160px; object-fit: contain; display: block; }
ha-markdown-element > div:nth-of-type(3) > div > div:first-child small { font-size: 10px; }
ha-markdown-element > div:nth-of-type(3) > div > div:last-child { min-width: 0; }
h3 { margin: 0 0 6px !important; font-size: 16px; line-height: 1.35; overflow-wrap: anywhere; }
h3 + p { color: var(--secondary-text-color); font-size: 13px; margin: 0 0 16px !important; }
h3 ~ span, h3 ~ mark, h3 ~ em { display: inline-block; font-size: 12px; font-weight: 700; font-style: normal; border-radius: 8px; padding: 5px 9px; }
h3 ~ span { color: var(--success-color,#228b58); background: rgba(34,139,88,.12); }
h3 ~ mark { color: var(--warning-color,#b87900); background: rgba(210,150,30,.13); }
h3 ~ em { color: var(--error-color,#db4437); background: rgba(219,68,55,.13); }
h3 ~ p:last-child { font-size: 12px; margin: 10px 0 0 !important; color: var(--secondary-text-color); }
ha-markdown-element > p:last-child { font-size: 12px; margin-top: 24px !important; }
@media(max-width:650px) { ha-markdown-element > div:nth-of-type(3) { grid-template-columns: 1fr; } h1 {font-size: 26px;} ha-markdown-element > div:nth-of-type(2) {gap:8px;} ha-markdown-element > div:nth-of-type(2) > div {padding:16px 10px;} ha-markdown-element > div:nth-of-type(2) span {font-size:11px;} ha-markdown-element > div:nth-of-type(3) > div {padding:16px; gap:16px;} }

