{%- set ns = namespace(found=false, records=[]) -%}
{%- for s in expand(integration_entities('winbiap')) if s.attributes.reservations is defined and s.state not in ['unknown','unavailable'] -%}
{%- set ns.found = true -%}{%- set ns.records = ns.records + s.attributes.reservations -%}
{%- endfor -%}
## Vorbestellungen
{% if not ns.found %}
<ha-alert alert-type="info">Vorbestellungen sind derzeit nicht verfügbar.</ha-alert>
{% elif not ns.records %}
Keine Vorbestellungen vorhanden.
{% else %}
**{{ ns.records | count }} vorgemerkt · {{ ns.records | selectattr('ready_for_pickup', 'equalto', true) | list | count }} abholbereit**
<table role="presentation">
{% for r in ns.records %}
<tr><td>{% for img in expand(integration_entities('winbiap')) if img.attributes.reservation_id | default('') == r.id and img.state not in ['unknown','unavailable'] %}<img src="{{ img.attributes.entity_picture | e }}" width="70" alt="Cover Vorbestellung">{% endfor %}</td><td><strong>{{ r.title | e }}</strong><br>{{ (r.author or '') | e }}<br>{{ (r.status or 'Status nicht angegeben') | e }}{% if r.pickup_deadline %}<br>Abholen bis: <strong>{{ as_datetime(r.pickup_deadline).strftime('%d.%m.%Y') }}</strong>{% endif %}</td></tr>
{% endfor %}
</table>
{% endif %}
